/// @file main.cpp
/// @brief C++ listener example - subscribes to std_msgs/String (manual-poll)

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#define RCLCPP_TRY_LOG(file, line, expr, ret)                                                      \
    fprintf(stderr, "[nros] %s:%d %s -> %d\n", (file), (line), (expr), (int)(ret))

#include <rclcpp/rclcpp.hpp>

// Generated C++ bindings for std_msgs/msg/String
#include "std_msgs.hpp"

// ----------------------------------------------------------------------------
// Application state
// ----------------------------------------------------------------------------

static volatile sig_atomic_t g_running = 1;

// ----------------------------------------------------------------------------
// Signal handler for graceful shutdown
// ----------------------------------------------------------------------------

static void signal_handler(int signum) {
    (void)signum;
    g_running = 0;
}

// ----------------------------------------------------------------------------
// Main
// ----------------------------------------------------------------------------

int main(int argc, char** argv) {
#ifdef _IOLBF /* absent on the bare-metal riscv64-threadx libc */
    setvbuf(stdout, nullptr, _IOLBF, 0);
#endif
    (void)argc;
    (void)argv;

    printf("nros C++ Listener\n");
    printf("===================\n");

    RCLCPP_TRY_RET(rclcpp::init_in(), 1);

    rclcpp::Node node;
    RCLCPP_TRY_RET(rclcpp::create_node(node, "@NODE@"), 1);
    printf("Node created: %s\n", node.get_name());

    rclcpp::PollSubscription<std_msgs::msg::String> sub;
    RCLCPP_TRY_RET(node.create_subscription(sub, "/chatter"), 1);
    printf("Subscriber created for topic: %s\n", "/chatter");

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("\nWaiting for messages (Ctrl+C to exit)...\n\n");

    int message_count = 0;

    // Alternative: use Stream::wait_next for blocking reception
    // std_msgs::msg::String msg;
    // sub.stream().wait_next(rclcpp::global_handle(), 1000, msg);

    // Spin + poll loop
    while (g_running && rclcpp::ok()) {
        rclcpp::spin_once(100);

        std_msgs::msg::String msg;
        while (sub.take(msg)) {
            message_count++;
            printf("I heard: [%s]\n", msg.data.c_str());
        }
    }

    // Cleanup
    printf("\nShutting down...\n");
    printf("Total messages received: %d\n", message_count);
    rclcpp::shutdown();

    printf("Goodbye!\n");
    return 0;
}
